-- One-time guarded recipe refinement. Preserve ingredient quantities and cooking guidance.
BEGIN;
DO $refine$
DECLARE item jsonb; affected integer;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements($payload$[{"id":"79aa5eff-60cf-4e52-8e33-23486c97fa48","digest":"a445cc8c5597e1bdfd2b6edcb50c40c7","detail":{"method":["Heat the oven to 200°C fan / 220°C conventional. Put the thighs on a lined roasting tray in one layer.","Mix the garlic, Cajun seasoning and 1 tbsp of the oil. Coat the thighs evenly. Keep Barney’s portion mild by using less Cajun seasoning on it; season the adult portions separately.","Roast for about 25–30 minutes, turning once if needed, until browned and the thickest part reaches 75°C for 30 seconds. Thickness affects cooking time: check rather than relying on the timer. Rest for 5 minutes, then slice across the grain.","While the chicken roasts, cook the rice using the water quantity and time on its packet. Rest covered off the heat for 5 minutes, fluff with a fork, then stir in the zest of 1 lime and lime juice to taste.","Heat the remaining 1 tbsp oil in a wide frying pan over medium-high heat. Fry the peppers and onion for 8–10 minutes, stirring occasionally so they colour rather than steam. Cook the sweetcorn according to its packet, then add to the pan and fry for 3–5 minutes until lightly charred.","Mix the tomatoes and avocado gently with the juice of 1 lime. Taste the adult salsa and adjust with lime and seasoning; keep it chilled until serving.","Serve sliced chicken with rice, smoky vegetables and salsa. Cut Barney’s cooked chicken and vegetables into suitable small pieces. Reserve the planned lunch portions with all components, packing salsa separately. Cool rice quickly, ideally within 1 hour, refrigerate and use within 24 hours."],"version":2,"ingredients":[{"prep":"leave whole; trim any large pieces of fat","label":"Boneless chicken thighs 850g"},{"prep":"rinse under cold water","label":"White rice 320g dry"},{"prep":"deseed and slice into 1cm strips","label":"Bell peppers 3"},{"prep":"use from frozen","label":"Frozen sweetcorn 300g"},{"prep":"peel, halve and slice into thin wedges","label":"Red onion 1"},{"prep":"dice into 1cm pieces","label":"Tomatoes 250g"},{"prep":"peel and dice into 1cm pieces just before serving","label":"Avocados 2"},{"prep":"zest 1; juice as needed; cut the remainder into wedges","label":"Limes 3"},{"prep":"peel and finely grate or crush","label":"Garlic 3 cloves"},{"prep":"","label":"Cajun seasoning 3 tbsp"},{"prep":"","label":"Olive oil 2 tbsp"}]}},{"id":"72e42b9a-667f-43de-8a1b-589178db5c1d","digest":"abac00475a71889b637ce2c99a6943f5","detail":{"method":["Heat the oven to 200°C fan / 220°C conventional. Keep the pastry refrigerated while making the filling.","Heat a wide non-stick pan over medium-high heat. Brown the chicken in two batches for 3–4 minutes each, using a splash of water if it starts sticking. Transfer to a plate; it will finish cooking in the filling.","Reduce to medium-low heat. Add the leeks with 2 tbsp water, cover and soften for 8–10 minutes, stirring occasionally. They should be soft, not browned.","Return the chicken to the pan. Add the stock, mustard and crème fraîche, bring to a gentle simmer and cook uncovered for 8–12 minutes, stirring. Add the frozen peas and cook for the packet’s recommended time. Stir in the tarragon. The filling should coat a spoon rather than look watery; simmer a little longer if necessary.","Taste and season the adult filling; keep Barney’s portion mildly seasoned. Put the filling into a baking dish and let it stop steaming strongly for 5–10 minutes so the pastry does not soften immediately.","Lay the pastry over the dish, trim if necessary and press onto the rim. Cut a small steam vent in the centre and brush lightly with beaten egg. Bake for 25–30 minutes until the top is risen and deeply golden and the centre is piping hot; check the chicken reaches 75°C for 30 seconds.","Meanwhile, spread the carrots on a lined tray, add a splash of water and cover with foil for 15 minutes. Uncover and roast for another 15–20 minutes until tender and lightly coloured. Steam the beans for 5–7 minutes until tender.","Rest the pie for 5 minutes. Divide pie, carrots and beans across the dinner and planned lunch allocations. Check Barney’s chicken and vegetables are soft and suitably cut. Cool the reserved portions promptly, refrigerate within 2 hours and reheat once until steaming throughout."],"version":2,"ingredients":[{"prep":"cut into roughly 2cm bite-size pieces","label":"Chicken breast 850g"},{"prep":"trim, split lengthways, rinse between the layers and slice into 5mm half-moons","label":"Leeks 3"},{"prep":"use from frozen","label":"Frozen peas 250g from stock"},{"prep":"keep chilled until needed","label":"Puff pastry 1 x 320g sheet"},{"prep":"measure","label":"Crème fraîche 300ml"},{"prep":"","label":"Chicken stock 300ml"},{"prep":"","label":"Mustard 2 tbsp from stock"},{"prep":"strip leaves from stems and finely chop","label":"Fresh tarragon 15g"},{"prep":"peel and cut into 1cm-thick diagonal slices; halve thick pieces","label":"Carrots 600g"},{"prep":"trim ends; cut smaller for Barney after cooking","label":"Green beans 400g"},{"prep":"beat for brushing; you may not need all of it","label":"Egg 1"}]}},{"id":"e0a39bf4-1be9-4c8a-8da2-fd1e49758c49","digest":"5ad8e1e0c2b33a171efbfff336b0fc6e","detail":{"method":["Heat a non-stick frying pan over medium heat. Season the adult chicken and cook for roughly 5–7 minutes each side, depending on thickness. Check the centre reaches 75°C for 30 seconds; add a splash of water and cover briefly if it is browning too fast.","Rest the chicken for 5 minutes, then cut across the grain into thin strips.","Mix mayonnaise, mustard and 1–2 tbsp lemon juice. Taste and add more lemon or black pepper as needed. Toss the lettuce with Parmesan and enough dressing to coat lightly.","Warm the wraps briefly to make them flexible. Divide chicken, dressed lettuce and tomato between them, fold in the sides and roll. If packing for later, cool chicken promptly and keep the wraps refrigerated; pack wet ingredients separately if you want the wraps to stay crisp."],"version":2,"ingredients":[{"prep":"slice horizontally into thinner cutlets if very thick","label":"Chicken breast 300g"},{"prep":"","label":"Large wraps 2"},{"prep":"wash, dry and shred into 1cm strips","label":"Romaine lettuce 1 small"},{"prep":"finely grate","label":"Parmesan 40g"},{"prep":"dice into 1cm pieces","label":"Tomatoes 150g"},{"prep":"juice","label":"Lemon 1"},{"prep":"","label":"Mustard 1 tsp"},{"prep":"","label":"Mayonnaise 30g"}]}},{"id":"da6192fd-fe31-430e-b505-761deda8138e","digest":"4285e0b78a3d9d19c480206509374686","detail":{"method":["Heat the oven to 200°C fan / 220°C conventional. Line a baking tray.","Toss the cabbage with the juice of 1 lime. Massage briefly with clean hands and leave for 10 minutes to soften. Mix yoghurt with chipotle paste and a little juice from the second lime; keep some plain yoghurt aside for Barney.","Pat the fish dry. Dip each strip in beaten egg, then press into the breadcrumbs on all sides. Arrange on the tray without crowding.","Bake for about 12–18 minutes, turning carefully halfway if needed, until the crumb is crisp and the fish is opaque and flakes easily. Thick strips may need longer; check the centre is steaming hot.","Cook the frozen sweetcorn as its packet directs, drain well, then char in a hot non-stick frying pan for 3–5 minutes, stirring occasionally.","Warm the tortillas in a dry pan for about 20–30 seconds each side, or follow the packet, and keep covered in a clean tea towel.","Fill tortillas with fish, slaw, corn, avocado, tomato, red onion and chipotle yoghurt. Finish with lime. Serve Barney a deconstructed plate with boneless fish, soft tortilla, avocado and suitable small pieces of vegetables; keep chilli sauce separate."],"version":2,"ingredients":[{"prep":"check for bones and cut into finger-size strips","label":"White fish fillets 500g"},{"prep":"","label":"Small tortillas 8"},{"prep":"remove tough core and shred very finely","label":"White cabbage 300g"},{"prep":"use from frozen","label":"Frozen sweetcorn 200g from stock"},{"prep":"peel and cut into thin slices","label":"Avocado 1"},{"prep":"dice into 1cm pieces","label":"Tomatoes 200g"},{"prep":"peel, halve and slice very finely","label":"Red onion 1"},{"prep":"juice; reserve wedges","label":"Limes 2"},{"prep":"","label":"Greek yoghurt 150g"},{"prep":"","label":"Chipotle paste 1 tbsp"},{"prep":"","label":"Breadcrumbs 80g from stock"},{"prep":"beat in a shallow bowl","label":"Egg 1"}]}},{"id":"fad6eb51-cc80-47b3-94af-37768cad2a62","digest":"5e99ad05390509bba87ba40b3a3693e2","detail":{"method":["Cook the fish fingers from frozen using the oven or air-fryer temperature and time on their packet. Turn if instructed and check they are steaming hot in the middle and crisp outside.","Mix mayonnaise, mustard and sesame seeds. Taste before adding anything else; the kimchi supplies salt and acidity.","Toast the cut sides of the brioche buns in a dry pan for 1–2 minutes until lightly golden.","Spread sauce on the buns, add fish fingers and kimchi, then close and serve straight away."],"version":2,"ingredients":[{"prep":"split horizontally","label":"Brioche buns 2 from stock"},{"prep":"use from frozen","label":"Fish fingers 6 from stock"},{"prep":"drain excess liquid and roughly chop","label":"Kimchi 80g from stock"},{"prep":"","label":"Mayonnaise 40g"},{"prep":"","label":"Mustard 1 tsp from stock"},{"prep":"","label":"Sesame seeds 1 tsp from stock"}]}},{"id":"2d060cb7-7f3c-4e9e-b29d-12ec7d4b4caf","digest":"d6ecde4ad543d73cc767590cc9d68866","detail":{"method":["Before heating the pan, stir the gochujang, soy sauce, rice vinegar and honey together with 3 tbsp water.","Cook dried noodles following the packet, then drain and briefly rinse so they do not stick. If using ready-cooked noodles, loosen them as the packet directs and add them later.","Heat a wide non-stick pan or wok over medium-high heat. Brown the beef in two batches if the pan is crowded, about 8–10 minutes total. Break it into small pieces and let moisture evaporate. Check it reaches 75°C for 30 seconds; drain excess fat, retaining a little in the pan.","Add the mushrooms and carrots. Stir-fry for 5–7 minutes until the mushrooms have lost their water and the carrots are tender-crisp. Stir in garlic and ginger for 1 minute.","Add the pak choi stems and stir-fry for 2–3 minutes. Add the sauce, bring to a simmer, then add noodles and pak choi leaves.","Toss with tongs for 2–3 minutes until the noodles are hot and coated and the leaves have wilted. Add water 1 tbsp at a time if the sauce is too thick.","Finish with spring onions, sesame seeds and lime juice to taste. Divide into the four planned adult portions. Cool lunch portions promptly, refrigerate within 2 hours and reheat once until steaming hot, loosening with a little water."],"version":2,"ingredients":[{"prep":"","label":"Beef mince 750g"},{"prep":"check whether dried or ready-cooked; follow the packet","label":"Egg noodles 500g"},{"prep":"wash, separate stems from leaves; cut stems into 1cm slices and leaves into broad strips","label":"Pak choi 2"},{"prep":"wipe clean and slice about 5mm thick","label":"Mushrooms 300g"},{"prep":"peel and cut into thin matchsticks","label":"Carrots 3"},{"prep":"trim and finely slice","label":"Spring onions 4 from stock"},{"prep":"peel and finely grate or crush","label":"Garlic 3 cloves"},{"prep":"peel and finely grate","label":"Fresh ginger 25g"},{"prep":"","label":"Gochujang 80g"},{"prep":"","label":"Soy sauce 3 tbsp"},{"prep":"","label":"Rice vinegar 2 tbsp"},{"prep":"","label":"Honey 1 tbsp"},{"prep":"","label":"Sesame seeds 2 tbsp from stock"},{"prep":"juice; reserve wedges if preferred","label":"Lime 1"}]}},{"id":"fd2fd782-e9b9-4997-b281-7051b1024070","digest":"99350be11a043c46cd4151efbe7de65a","detail":{"method":["Mix half the garlic with the oregano, zest of 1 lemon, juice of 2 lemons and about half the olive oil. Coat the pork and refrigerate for 20–30 minutes. Soak wooden skewers in water for 30 minutes, or use metal skewers.","Heat the oven to 200°C fan / 220°C conventional. Toss potatoes with most of the remaining oil and spread over two trays if needed. Roast for 25 minutes, turning once.","Add the peppers to the potato trays, spreading everything in one layer. Roast for another 20–25 minutes until the potatoes are tender inside and browned outside and the peppers have softened.","Thread the pork loosely onto skewers. Cook under a preheated medium-high grill for about 12–18 minutes, turning every 3–4 minutes. Keep the tray below the grill so the marinade does not burn. Cook in batches if necessary; check the centre of the thickest piece reaches 75°C for 30 seconds, then rest for 5 minutes.","Meanwhile, squeeze excess water from the grated cucumber and mix with the yoghurt. Add the remaining garlic gradually, lemon juice to taste and a little seasoning for adults. Keep chilled.","Mix the tomatoes, remaining cucumber, red onions and leaves. Dress with lemon juice and the last little oil just before serving.","Serve pork off the skewers with potatoes, peppers, tzatziki and salad. Cut Barney’s meat into tender suitable pieces. Reserve the planned lunch portions from this enlarged batch; keep salad and tzatziki separate from cooked pork and vegetables. Cool cooked portions promptly, refrigerate within 2 hours and reheat once until steaming throughout."],"version":2,"ingredients":[{"prep":"trim and cut into even 2.5cm cubes","label":"Pork loin 1.1kg"},{"prep":"halve small potatoes; quarter larger ones to about 3cm","label":"Baby potatoes 1.3kg"},{"prep":"deseed and cut into broad 3cm pieces","label":"Bell peppers 4"},{"prep":"dice into 1–2cm pieces","label":"Tomatoes 450g"},{"prep":"wash; grate half for tzatziki and dice the rest","label":"Cucumber 2"},{"prep":"peel, halve and slice thinly","label":"Red onions 2"},{"prep":"","label":"Greek yoghurt 450g"},{"prep":"zest and juice as needed; reserve wedges","label":"Lemons 4"},{"prep":"peel and finely grate or crush","label":"Garlic 6 cloves"},{"prep":"","label":"Dried oregano 3.5 tbsp"},{"prep":"wash and dry","label":"Salad leaves 2 bags"},{"prep":"","label":"Olive oil 3.5 tbsp"}]}},{"id":"fed15c7f-1be9-4746-b026-83244a9fa7b5","digest":"93af714c6fc49e04990d3d9b5d8b3a56","detail":{"method":["Heat the oven to 200°C fan / 220°C conventional. Toss with 1 tbsp oil and spread in one layer on a roasting tray.","Roast for about 25–35 minutes, turning after 15 minutes, until browned at the edges and easily pierced with a fork. Allow to cool for 5 minutes.","Put the couscous in a heatproof bowl and add the boiling-water quantity specified on its packet. Cover for the packet’s recommended time, usually 5–10 minutes, then fluff thoroughly with a fork.","Whisk the remaining 1 tbsp oil with mustard and 1–2 tbsp lemon juice. Taste and adjust the lemon before dressing the salad.","Toss warm squash and couscous with the dressing, then gently fold through leaves and feta. Add walnuts to the adult portions just before serving.","Serve Barney soft squash, couscous and crumbled feta without walnut pieces. If keeping any portions, cool promptly, refrigerate within 2 hours and keep leaves separate where possible."],"version":2,"ingredients":[{"prep":"peel, remove seeds and cut into even 2cm cubes","label":"Butternut squash 1 medium"},{"prep":"measure dry; follow packet water quantity","label":"Couscous 180g from stock"},{"prep":"crumble","label":"Feta 150g"},{"prep":"roughly chop for adults; omit pieces from Barney’s serving","label":"Walnuts 50g from stock"},{"prep":"wash and dry","label":"Salad leaves 1 bag"},{"prep":"juice","label":"Lemon 1"},{"prep":"","label":"Mustard 1 tsp from stock"},{"prep":"","label":"Olive oil 2 tbsp"}]}},{"id":"0743bc2b-c055-4f67-bf52-2284dcfb0eff","digest":"a9d7696392236f9b7982080733a89d47","detail":{"method":["Heat the oven to 150°C fan / 170°C conventional. Pat the lamb dry; use a heavy casserole with a lid.","Heat 1 tbsp oil over medium-high heat. Brown the lamb in two or three batches for 3–4 minutes each, leaving space between pieces. Transfer to a plate.","Add the remaining oil and cook the aubergine in batches for 5–7 minutes until browned on several sides. Transfer to a plate. Reduce the heat and soften the onions for 8–10 minutes, adding a splash of water if they catch.","Add garlic and the cumin, cinnamon, turmeric and coriander; stir for 1 minute. Return lamb and aubergine, add the tomatoes and about 300ml water. Scrape up the browned bits. The liquid should nearly reach the meat; add a little more water if needed.","Bring to a gentle simmer, cover and cook in the oven for about 2–2½ hours, stirring once halfway. The lamb should pull apart easily with a fork and the aubergine should be soft. If needed, cook longer; add small splashes of water to prevent drying.","If the sauce is too loose, remove the lid and simmer on the hob for 10–15 minutes. Stir in the spinach for 2–3 minutes until wilted. Add lemon juice gradually and taste the adult seasoning.","Near the end of the stew’s cooking time, cook the rice following its packet and rest covered for 5 minutes. Finish the stew with parsley and coriander and serve with rice. Cut Barney’s tender lamb suitably and allow his serving to cool."],"version":2,"ingredients":[{"prep":"trim and cut any large pieces into even 3cm cubes","label":"Diced lamb 650g"},{"prep":"trim and cut into roughly 2.5cm chunks","label":"Aubergines 2"},{"prep":"","label":"Tinned tomatoes 1 x 400g from stock"},{"prep":"wash; roughly chop large leaves","label":"Spinach 200g"},{"prep":"peel and dice into about 1cm pieces","label":"Onions 2"},{"prep":"peel and finely chop","label":"Garlic 4 cloves"},{"prep":"rinse under cold water","label":"White rice 220g dry from stock"},{"prep":"pick leaves and finely chop","label":"Fresh parsley 30g"},{"prep":"roughly chop leaves and tender stems","label":"Fresh coriander 30g"},{"prep":"juice; reserve wedges","label":"Lemon 1"},{"prep":"","label":"Ground cumin 2 tsp"},{"prep":"","label":"Ground cinnamon 1 tsp"},{"prep":"","label":"Ground turmeric 1 tsp"},{"prep":"","label":"Ground coriander 2 tsp"},{"prep":"","label":"Olive oil 2 tbsp"}]}},{"id":"afc31b35-e938-4956-b331-499baee86977","digest":"ad832ae18f6b87bf2d4d5a8fa6749666","detail":{"method":["Keep the salad and herbs separate from the hot ingredients.","Cook the rice following its packet instructions. Rest covered for 5 minutes off the heat, then fluff.","Heat a large non-stick frying pan over medium-high heat. Add the beef in two batches if needed. Press it into the pan and leave for 2–3 minutes before breaking it up; cook for about 8–10 minutes in total until browned and cooked through. Drain excess fat if necessary, leaving a little to carry the flavour.","Add the garlic and ginger. Stir for 1–2 minutes until fragrant. Check the mince is thoroughly cooked; a thermometer should read 75°C for 30 seconds.","Remove Barney’s lightly seasoned beef before adding the full sauce. Stir the fish sauce, soy sauce and sugar into the adult beef, then remove from the heat. Add the juice of 2 limes, taste and use the third to adjust: the result should be savoury and sharp, with only a little sweetness.","Divide rice, beef and all the vegetables between the planned servings. Finish adult portions with spring onions, mint and coriander. Finely cut or soften Barney’s vegetables as appropriate.","Pack lunch beef and rice separately from the cold salad and herbs. Cool rice quickly, ideally within 1 hour, refrigerate and use within 24 hours. Reheat the hot components once until steaming throughout, then add the chilled salad."],"version":2,"ingredients":[{"prep":"","label":"Beef mince 750g"},{"prep":"rinse under cold water","label":"White rice 320g dry"},{"prep":"halve lengthways and cut into thin half-moons","label":"Cucumber 1"},{"prep":"peel and grate coarsely or cut into fine matchsticks","label":"Carrots 3"},{"prep":"peel, halve and slice very thinly","label":"Red onion 1"},{"prep":"wash, dry and shred","label":"Romaine lettuce 1"},{"prep":"trim and finely slice","label":"Spring onions 4 from stock"},{"prep":"pick leaves and roughly chop","label":"Fresh mint 30g"},{"prep":"roughly chop leaves and tender stems","label":"Fresh coriander 30g"},{"prep":"juice; reserve wedges for serving","label":"Limes 3"},{"prep":"peel and finely grate or crush","label":"Garlic 3 cloves"},{"prep":"peel and finely grate","label":"Fresh ginger 25g"},{"prep":"","label":"Fish sauce 3 tbsp"},{"prep":"","label":"Soy sauce 2 tbsp"},{"prep":"","label":"Brown sugar 1 tbsp"}]}}]$payload$::jsonb) LOOP
 UPDATE public.meals SET recipe_detail=item->'detail', recipe_revision=recipe_revision+1
 WHERE id=(item->>'id')::uuid AND recipe_revision=1 AND md5(recipe_detail::text)=item->>'digest';
 GET DIAGNOSTICS affected = ROW_COUNT;
 IF affected <> 1 THEN RAISE EXCEPTION 'Recipe changed: %', item->>'id'; END IF;
 END LOOP;
END $refine$;
COMMIT;
